@font-face{font-family:"Nanum Pen Script";font-weight:400;font-display:swap;src:url("../fonts/NanumPenScript-400.woff2") format("woff2")}


/* 와우 포인트 38 — 발표 와우 기법을 열 묶음으로 모은 13장 덱.
   이미지 자리: --img-A … --img-H 에 사진을 넣으면 바뀐다(없으면 점선 자리표시). */
@property --x { syntax: '<percentage>'; inherits: true; initial-value: 50%; }
@property --a { syntax: '<angle>'; inherits: false; initial-value: 0deg; }
@property --lx { syntax: '<percentage>'; inherits: true; initial-value: 50%; }
@property --ly { syntax: '<percentage>'; inherits: true; initial-value: 50%; }
@property --lr { syntax: '<length>'; inherits: true; initial-value: 0px; }
@property --lm { syntax: '<number>'; inherits: true; initial-value: 1; }
:root{
  --bg:#ECE9E3; --paper:#F7F5F1; --surface:#FFFFFF; --ink:#1C2128; --sub:#5C636C; --mute:#9AA0A7; --line:#DAD5CC;
  --accent:#E2571A;
  --g1:#2F5D86; --g2:#7B4F9E; --g3:#C4471A; --g4:#2E7D5B; --g5:#A87C00; --g6:#B0306A; --g7:#12808C; --g8:#617510; --g9:#A8323E; --g10:#4A5563;
  --ft:"Gothic A1","Apple SD Gothic Neo","Malgun Gothic",sans-serif;
  --fb:"IBM Plex Sans KR","Apple SD Gothic Neo","Malgun Gothic",sans-serif;
  --fm:"IBM Plex Mono",ui-monospace,monospace;
  /* 이미지 자리(받으면 채움) */
  --img-A:url(data:image/webp;base64,); --img-B:url(data:image/webp;base64,); --img-C1:url(data:image/webp;base64,); --img-C2:url(data:image/webp;base64,);
  --img-D:url(data:image/webp;base64,); --img-E:url(data:image/webp;base64,); --img-F:url(data:image/webp;base64,); --img-H:url(data:image/webp;base64,);
  --img-N:url(data:image/webp;base64,); /* 불꽃 배경: 밤바다 · 다리 */
  --img-LI:url(data:image/webp;base64,); --img-LO:url(data:image/webp;base64,); /* 렌즈 속 장면: 불 켜진 · 꺼진 같은 학교(사용자 제공 AI 사진) */
}
*{box-sizing:border-box}
html,body{margin:0;height:100%;background:#22262C;color:var(--ink);font-family:var(--fb);-webkit-font-smoothing:antialiased}
.viewport{position:fixed;inset:0 0 56px 0;overflow:hidden}
/* 무대는 화면 정중앙 기준으로 줄임(화면이 1600px보다 좁아도 밀리지 않게) */
.stage{width:1600px;height:900px;position:absolute;left:50%;top:50%;transform-origin:center center}
.slide{position:absolute;inset:0;background:var(--paper);overflow:hidden;visibility:hidden;opacity:0;transition:opacity .35s}
.slide.on{visibility:visible;opacity:1}
.bar{position:fixed;left:0;right:0;bottom:0;height:56px;display:flex;align-items:center;justify-content:center;gap:10px;color:#C9CDD2;font:500 14px var(--fm)}
.bar button{font:500 14px var(--fb);color:#fff;background:#363B43;border:0;border-radius:6px;padding:8px 14px;cursor:pointer}
.bar button:hover{background:#4A5059}
.bar button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.bar .count{min-width:64px;text-align:center}
.bar a{color:#C9CDD2;font-size:13px;margin-left:14px}

/* 공통 머리 */
.head{position:absolute;left:64px;right:64px;top:52px;display:flex;align-items:flex-end;justify-content:space-between;gap:40px}
.chip{display:inline-flex;align-items:center;gap:10px;font:700 20px var(--fb);color:var(--gc)}
.chip b{display:inline-grid;place-items:center;width:34px;height:34px;border-radius:50%;background:var(--gc);color:#fff;font:700 18px var(--fm)}
.head h2{margin:14px 0 0;font:800 50px/1.18 var(--ft);letter-spacing:-.02em}
.head .meta{font:500 16px var(--fm);color:var(--sub);text-align:right;white-space:nowrap;padding-bottom:8px}
.foot{position:absolute;left:64px;right:64px;bottom:26px;display:flex;justify-content:space-between;font:500 13px var(--fm);color:var(--mute)}

/* 카드 */
.cards{position:absolute;left:64px;right:64px;top:232px;bottom:62px;display:grid;gap:26px}
.cards.c3{grid-template-columns:repeat(3,1fr)}
.cards.c4{grid-template-columns:repeat(4,1fr)}
.cards.c5{grid-template-columns:repeat(5,1fr);gap:18px}
.c5 .card{padding:12px 12px 14px}
.c5 .demo{aspect-ratio:4/3}
.c5 .steps{font-size:12.5px}
.c5 .card h3{font-size:22px;margin-top:10px}
.c5 .card h3 small{font-size:13px}
.c5 .card .why{font-size:15px;margin-top:6px}
.c5 .card dl{font-size:13.5px;gap:5px 9px;padding-top:10px}
.card{background:var(--surface);border-radius:14px;padding:14px 14px 18px;display:flex;flex-direction:column;box-shadow:0 1px 0 var(--line),0 10px 24px -18px rgba(28,33,40,.35);border-top:4px solid var(--gc)}
.demo{position:relative;border-radius:8px;overflow:hidden;background:#F1EEE8;container-type:size;aspect-ratio:1/.9;flex:none}
.c3 .demo{aspect-ratio:4/3}
.steps{margin:10px 2px 0;font:500 14px var(--fb);color:var(--sub);letter-spacing:-.01em}
.steps i{font-style:normal;color:var(--gc)}
.card h3{margin:14px 2px 0;font:800 27px/1.2 var(--ft);letter-spacing:-.02em}
.card h3 small{font:500 15px var(--fb);color:var(--sub);margin-left:6px;letter-spacing:0}
.card .why{margin:8px 2px 0;font:500 18px/1.45 var(--fb)}
.card dl{margin:auto 2px 0;padding-top:12px;display:grid;grid-template-columns:auto 1fr;gap:7px 12px;font:400 15px/1.45 var(--fb);border-top:1px solid var(--line)}
.c3 .card dl{font-size:16px}
.card dt{font-weight:700;color:var(--gc);white-space:nowrap}
.card dd{margin:0;color:#343A42}
.g1{--gc:var(--g1)} .g2{--gc:var(--g2)} .g3{--gc:var(--g3)} .g4{--gc:var(--g4)} .g5{--gc:var(--g5)} .g6{--gc:var(--g6)} .g7{--gc:var(--g7)} .g8{--gc:var(--g8)} .g9{--gc:var(--g9)} .g10{--gc:var(--g10)}

/* 이미지 자리 */
.img{position:absolute;inset:0;background-size:cover;background-position:center}
.img.need{background-image:repeating-linear-gradient(135deg,#E4E0D8 0 10px,#EDEAE4 10px 20px)}
.img.need::after{content:attr(data-need);position:absolute;left:6%;right:6%;top:50%;transform:translateY(-50%);padding:.5em .7em;border:1.5px dashed #9A948A;border-radius:6px;background:rgba(255,255,255,.88);font:600 3.6cqw/1.35 var(--fb);color:#5C564D;text-align:center}

/* ── 1 표지 ── */
.cover{background:var(--paper)}
.cover .kick{position:absolute;left:96px;top:96px;font:500 18px var(--fm);color:var(--sub);letter-spacing:.04em}
.cover h1{position:absolute;left:92px;top:150px;margin:0;font:900 170px/0.98 var(--ft);letter-spacing:-.045em}
.cover h1 em{font-style:normal;color:var(--accent)}
.cover .sub{position:absolute;left:96px;top:520px;width:640px;margin:0;font:500 28px/1.5 var(--fb)}
.cover .by{position:absolute;left:96px;bottom:64px;font:500 16px var(--fm);color:var(--sub)}
.burst{position:absolute;right:80px;top:120px;width:560px;height:660px}
.burst .blk{position:absolute;border-radius:14px;display:flex;flex-direction:column;justify-content:flex-end;padding:18px 20px;color:#fff;font:700 22px var(--fb)}
.burst .blk b{font:800 44px/1 var(--ft);letter-spacing:-.03em}
.burst .blk{padding:12px 18px}
.burst .blk span{font:500 15px var(--fm);opacity:.85;margin-top:4px}
.play .burst .blk{animation:pop .7s cubic-bezier(.2,1.4,.4,1) both;animation-delay:calc(var(--i)*.12s + .2s)}
@keyframes pop{from{opacity:0;transform:translateY(40px) scale(.85)}to{opacity:1;transform:none}}

/* ── 2 한눈에 ── */
.map{position:absolute;left:64px;right:64px;top:218px;bottom:118px;display:grid;grid-template-columns:repeat(5,1fr);grid-template-rows:1fr 1fr;gap:12px}
.map .grp{padding:12px 12px 10px;border-top-width:5px}.map .grp h3{font-size:20px;margin:2px 0 6px}.map .grp p,.map .grp li small,.map .grp .go{display:none}.map .grp ol{gap:5px}.map .grp li{font-size:14.5px;padding:5px 9px}
.grp{background:var(--surface);border-radius:14px;padding:18px 16px 16px;border-top:6px solid var(--gc);display:flex;flex-direction:column;cursor:pointer;text-decoration:none;color:inherit;transition:transform .2s}
.grp:hover{transform:translateY(-4px)}
.grp .n{font:700 16px var(--fm);color:var(--gc)}
.grp h3{margin:6px 0 4px;font:800 25px/1.2 var(--ft);letter-spacing:-.02em}
.grp p{margin:0 0 14px;font:400 14px/1.45 var(--fb);min-height:41px;color:var(--sub)}
.grp ol{margin:0;padding:0;list-style:none;display:grid;gap:10px}
.grp li{font:600 17px/1.3 var(--fb);padding:9px 11px;border-radius:8px;background:#F4F2EE}
.grp li small{display:block;font:400 13px var(--fb);color:var(--sub);margin-top:2px}
.grp .go{margin-top:auto;padding-top:14px;font:500 14px var(--fm);color:var(--gc)}
.offs{position:absolute;left:64px;right:64px;bottom:62px;height:66px;display:flex;align-items:center;gap:18px;padding:0 24px;border:1.5px dashed #B9B3A8;border-radius:12px;font:500 18px var(--fb);color:var(--sub)}
.offs b{color:var(--ink)}
.play .grp{animation:pop .6s cubic-bezier(.2,1.3,.4,1) both;animation-delay:calc(var(--i)*.08s)}

/* ── ① 리빌 ── */
.d-reveal .door{position:absolute;top:0;bottom:0;width:50.5%;background:#E9E3D7;display:flex;align-items:center;justify-content:flex-end;padding:0 4cqw;font:800 9cqw/1 var(--ft);color:#3B3630;letter-spacing:-.03em}
.d-reveal .door.l{left:0;box-shadow:inset -1px 0 0 #CFC6B6}
.d-reveal .door.r{right:0;justify-content:flex-start;box-shadow:inset 1px 0 0 #CFC6B6}
.d-reveal .door::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(0deg,rgba(0,0,0,.025) 0 2px,transparent 2px 5px)}
.play .d-reveal .door.l{animation:openL 1.3s cubic-bezier(.7,0,.2,1) 1s both}
.play .d-reveal .door.r{animation:openR 1.3s cubic-bezier(.7,0,.2,1) 1s both}
@keyframes openL{to{transform:translateX(-101%)}}
@keyframes openR{to{transform:translateX(101%)}}
.d-reveal .after{position:absolute;left:6%;bottom:9%;font:800 8cqw/1.1 var(--ft);color:#fff;text-shadow:0 2px 12px rgba(0,0,0,.35);opacity:0}
.play .d-reveal .after{animation:fadeUp .6s 2.1s both}
@keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}

/* ── ① 점진적 공개 ── */
.d-build{background:#F6F4EF}
.d-build svg{position:absolute;inset:0;width:100%;height:100%}
.d-build rect{rx:5}
.d-build text{font:700 11px var(--fb);text-anchor:middle;dominant-baseline:central}
.d-build .ln{stroke:#B7B0A4;stroke-width:1.4;fill:none}
.d-build .lv{transform-box:fill-box}
.play .d-build .l1{animation:up .5s .2s both,dim .4s 1.4s forwards}
.play .d-build .l2{animation:up .5s 1.1s both,dim .4s 2.4s forwards}
.play .d-build .l3{animation:up .5s 2.1s both}
@keyframes up{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
@keyframes dim{to{opacity:.32}}
.d-build .cur{position:absolute;right:4%;top:5%;font:600 4cqw var(--fm);color:var(--g1)}

/* ── ① 줌 인 ── */
.d-zoom .world{position:absolute;inset:0;transform-origin:74% 25%}
.play .d-zoom .world{animation:zoom 5s cubic-bezier(.65,0,.25,1) .4s both}
@keyframes zoom{0%,18%{transform:none}38%,72%{transform:scale(2.4)}92%,100%{transform:none}}
.d-zoom .spot{position:absolute;left:50%;top:5%;width:47%;height:42%;border:.6cqw solid var(--accent);border-radius:1.4cqw;opacity:0}
.play .d-zoom .spot{animation:fadeIn .4s .5s both}
.d-zoom .zl{position:absolute;left:4%;bottom:6%;background:#fff;border-radius:1.4cqw;padding:2.4cqw 3cqw;font:600 4cqw/1.35 var(--fb);box-shadow:0 6px 18px -8px rgba(0,0,0,.4);opacity:0}
.d-zoom .zl b{display:block;font:800 5.4cqw var(--ft);color:var(--accent)}
.play .d-zoom .zl{animation:zlab 5s .4s both}
@keyframes zlab{0%,36%{opacity:0;transform:translateY(8px)}44%,70%{opacity:1;transform:none}80%,100%{opacity:0}}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.d-zoom .back{position:absolute;right:3%;top:4%;font:600 3.4cqw var(--fm);color:#fff;background:rgba(28,33,40,.75);padding:.6cqw 1.6cqw;border-radius:99px;opacity:0}
.play .d-zoom .back{animation:fadeIn .4s 5s both}

/* ── ① 허브 이동 ── */
.d-hub{background:#F6F4EF}
.d-hub .t{position:absolute;border-radius:1.8cqw;padding:2.4cqw 2.8cqw;display:flex;flex-direction:column;justify-content:space-between;color:#fff;font:600 3.6cqw var(--fb)}
.d-hub .t b{font:800 9cqw/1 var(--ft);letter-spacing:-.03em}
.d-hub .t.s b{font-size:6cqw}
.d-hub .open{position:absolute;inset:0;background:#7A5BB0;color:#fff;padding:5cqw 6cqw;clip-path:inset(4% 27% 52% 49% round 1.8cqw);opacity:0;display:flex;flex-direction:column;justify-content:center}
.d-hub .open>*{opacity:0}
.d-hub .open b{font:800 17cqw/1 var(--ft);letter-spacing:-.04em}
.d-hub .open span{font:600 4.4cqw/1.4 var(--fb)}
.play .d-hub .open{animation:hub 5s cubic-bezier(.65,0,.25,1) .5s both}
.play .d-hub .open>*{animation:hubIn 5s .5s both}
@keyframes hub{0%{opacity:0;clip-path:inset(4% 27% 52% 49% round 1.8cqw)}10%,22%{opacity:1;clip-path:inset(4% 27% 52% 49% round 1.8cqw)}38%,72%{opacity:1;clip-path:inset(0 0 0 0 round 0)}88%{opacity:1;clip-path:inset(4% 27% 52% 49% round 1.8cqw)}100%{opacity:0;clip-path:inset(4% 27% 52% 49% round 1.8cqw)}}
@keyframes hubIn{0%,38%{opacity:0}46%,68%{opacity:1}76%,100%{opacity:0}}
.d-hub .cursor{position:absolute;left:62%;top:30%;width:5cqw;height:5cqw;border-radius:50%;border:.6cqw solid #fff;box-shadow:0 0 0 .4cqw rgba(28,33,40,.5);opacity:0}
.play .d-hub .cursor{animation:tap .8s .1s both}
@keyframes tap{0%{opacity:0;transform:scale(1.6)}50%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(.8)}}

/* ── ② 비포/애프터 ── */
.d-ba{cursor:ew-resize;touch-action:none}
.d-ba .after{clip-path:inset(0 0 0 var(--x))}
.d-ba .handle{position:absolute;top:0;bottom:0;left:var(--x);width:.5cqw;margin-left:-.25cqw;background:#fff;box-shadow:0 0 0 1px rgba(0,0,0,.12)}
.d-ba .handle::after{content:"◀ ▶";position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:#fff;color:var(--ink);border-radius:99px;padding:1cqw 1.8cqw;font:700 2.8cqw var(--fm);white-space:nowrap;box-shadow:0 2px 8px rgba(0,0,0,.25)}
.d-ba .tag{position:absolute;top:4%;padding:.6cqw 1.8cqw;border-radius:99px;background:rgba(28,33,40,.78);color:#fff;font:700 3.4cqw var(--fb)}
.d-ba .tag.b{left:3%} .d-ba .tag.a{right:3%;background:var(--accent)}
.play .d-ba{animation:sweep 3.6s cubic-bezier(.65,0,.3,1) .5s both}
@keyframes sweep{0%,12%{--x:100%}55%{--x:0%}100%{--x:50%}}
.d-ba.drag{animation:none!important}

/* ── ② 연속 변형 ── */
.d-morph{background:#F6F4EF}
.d-morph .tile{position:absolute;transition:all .9s cubic-bezier(.65,0,.25,1);display:flex;align-items:flex-end;padding:1.2cqw 1.6cqw;color:#fff;font:700 3.6cqw/1.1 var(--fb);overflow:hidden;white-space:nowrap}
.d-morph .tile span{transition:opacity .4s}
.d-morph .cap{position:absolute;left:4%;top:4%;font:700 4.2cqw var(--fb);z-index:2;background:rgba(246,244,239,.92);padding:.4cqw 1.4cqw;border-radius:.8cqw}
.d-morph .tot{position:absolute;left:0;right:0;top:38%;text-align:center;color:#fff;font:800 12cqw/1 var(--ft);transition:opacity .5s;z-index:1}

/* ── ② 수미상관 ── */
.d-loop{background:#F6F4EF}
.d-loop svg{position:absolute;inset:0;width:100%;height:100%}
.d-loop .ring{fill:none;stroke:#D6D0C5;stroke-width:5}
.d-loop .prog{fill:none;stroke:var(--g2);stroke-width:5;stroke-linecap:round;stroke-dasharray:100 100;stroke-dashoffset:100;transform:rotate(-90deg);transform-origin:160px 100px}
.play .d-loop .prog{animation:draw 3.2s linear .4s both}
@keyframes draw{to{stroke-dashoffset:0}}
.d-loop .node circle{fill:#fff;stroke:#BDB6AA;stroke-width:2}
.d-loop .node text{font:700 10px var(--fb);text-anchor:middle;dominant-baseline:central;fill:#5C636C}
.play .d-loop .node circle{animation:lit .3s both;animation-delay:calc(var(--k)*.533s + .4s)}
.play .d-loop .node text{animation:litT .3s both;animation-delay:calc(var(--k)*.533s + .4s)}
@keyframes lit{to{fill:var(--g2);stroke:var(--g2)}}
@keyframes litT{to{fill:#fff}}
.d-loop .rot{transform-origin:160px 100px}
.play .d-loop .rot{animation:spin 3.2s linear .4s both}
@keyframes spin{from{transform:rotate(0)}to{transform:rotate(360deg)}}
.d-loop .dot{fill:var(--accent)}
.d-loop .ctr{font:800 15px var(--ft);text-anchor:middle;fill:var(--ink)}
.d-loop .ctr2{font:600 9.5px var(--fb);text-anchor:middle;fill:var(--accent);opacity:0}
.play .d-loop .ctr2{animation:fadeIn .5s 3.7s both}
.d-loop .start circle{stroke:var(--accent);stroke-width:3}
.play .d-loop .start .halo{animation:halo 1.2s 3.6s ease-out 2}
.d-loop .halo{fill:none;stroke:var(--accent);stroke-width:2;opacity:0;transform-box:fill-box;transform-origin:center}
@keyframes halo{from{opacity:.9;transform:scale(1)}to{opacity:0;transform:scale(2.2)}}

/* ── ③ 큰 숫자 ── */
.d-big{background:#fff;padding:7% 7%}
.d-big .lead{font:600 4.4cqw/1.4 var(--fb);color:var(--sub)}
.d-big .num{font:900 34cqw/0.9 var(--ft);letter-spacing:-.05em;color:var(--g3);margin-top:1cqw}
.d-big .num small{font-size:.42em;letter-spacing:-.02em}
.d-big .rest{position:absolute;left:7%;right:7%;bottom:6%;display:flex;gap:6cqw;font:600 4.2cqw var(--fb);color:#A7ACB2;border-top:1px solid #E8E5DF;padding-top:2.4cqw}
.d-big .rest b{display:block;font:800 6cqw var(--ft);color:#B9BDC2}
.play .d-big .num{animation:bigIn .8s cubic-bezier(.2,1.3,.4,1) .3s both}
.play .d-big .rest{animation:fadeIn .6s 1.2s both}
@keyframes bigIn{from{opacity:0;transform:scale(.6);transform-origin:left bottom}to{opacity:1;transform:none}}

/* ── ③ 단위 차트 ── */
.d-unit{background:#fff;display:flex;flex-direction:column;justify-content:center;gap:4cqw;padding:0 8%}
.d-unit .grid{display:grid;grid-template-columns:repeat(10,1fr);gap:.9cqw;width:64cqw;flex:none;align-self:center}
.d-unit .grid i{aspect-ratio:1;border-radius:.6cqw;background:#E6E2DA}
.d-unit .grid i.on{background:#E6E2DA}
.play .d-unit .grid i.on{animation:fill .25s both;animation-delay:calc(var(--i)*35ms + .3s)}
@keyframes fill{from{background:#E6E2DA;transform:scale(.6)}to{background:var(--g3);transform:none}}
.d-unit .txt{font:600 4.6cqw/1.3 var(--fb);color:var(--sub);display:flex;align-items:baseline;gap:2.4cqw;width:64cqw;align-self:center;white-space:nowrap}
.d-unit .txt b{font:900 13cqw/1 var(--ft);color:var(--ink);letter-spacing:-.04em}
.d-unit .txt em{font-style:normal;display:inline-block;margin-left:auto;padding:.5cqw 1.4cqw;border:1px solid var(--line);border-radius:99px;font:600 3.4cqw var(--fm)}

/* ── ③ 카운트업 ── */
.d-count{background:#1E2329;color:#fff;padding:9% 8%}
.d-count .lab{font:600 4.4cqw var(--fb);color:#AEB4BB}
.d-count .val{font:900 20cqw/1 var(--ft);letter-spacing:-.04em;margin-top:2cqw;font-variant-numeric:tabular-nums}
.d-count .val small{font-size:.3em;color:#AEB4BB;margin-left:1cqw}
.d-count .track{position:absolute;left:8%;right:8%;bottom:10%;height:2.4cqw;border-radius:99px;background:#39404A;overflow:hidden}
.d-count .track i{position:absolute;inset:0;width:0;background:var(--g3);border-radius:99px}
.d-count .goal{position:absolute;right:8%;bottom:15%;font:600 3.4cqw var(--fm);color:#AEB4BB}
.d-count.done .val{color:#FFB48A}

/* ── ③ 데이터 레이스 ── */
.d-race{background:#fff}
.d-race .yr{position:absolute;right:4%;bottom:4%;font:900 13cqw/1 var(--ft);color:#ECE8E1;letter-spacing:-.04em}
.d-race .row{position:absolute;left:4%;right:12%;height:14%;transition:transform .6s cubic-bezier(.6,0,.3,1)}
.d-race .row .bar{height:100%;border-radius:.6cqw;transition:width .6s cubic-bezier(.6,0,.3,1);display:flex;align-items:center;padding-left:1.6cqw;color:#fff;font:700 3.4cqw var(--fb);white-space:nowrap;min-width:max-content}
.d-race .row .v{position:absolute;top:50%;transform:translateY(-50%);font:600 3.2cqw var(--fm);color:var(--sub);margin-left:1.2cqw;transition:left .6s cubic-bezier(.6,0,.3,1)}
.d-race .rk{position:absolute;left:4%;top:3%;font:600 3.4cqw var(--fm);color:var(--sub)}

/* ── ④ 시각 은유 ── */
.d-meta .call{position:absolute;font:700 3.6cqw/1.3 var(--fb);background:#fff;border-radius:1cqw;padding:1cqw 1.8cqw;box-shadow:0 4px 14px -6px rgba(0,0,0,.35);opacity:0;white-space:nowrap}
.d-meta .call b{color:var(--g4)}
.d-meta .call::after{content:"";position:absolute;width:1.4cqw;height:1.4cqw;border-radius:50%;background:var(--g4);box-shadow:0 0 0 .6cqw rgba(46,125,91,.25)}
.d-meta .c1{left:3%;top:22%} .d-meta .c1::after{left:45%;top:calc(100% + 3cqw)}
.d-meta .c2{left:31%;top:12%} .d-meta .c2::after{left:47%;top:calc(100% + 13cqw)}
.d-meta .c3{right:3%;top:22%} .d-meta .c3::after{left:50%;top:calc(100% + 3.5cqw)}
.play .d-meta .call{animation:fadeUp .5s both;animation-delay:calc(var(--i)*.5s + .6s)}

/* ── ④ 생활 서식(탑승권) ── */
.d-ticket{background:#2F5D86;display:grid;place-items:center}
.tk{position:relative;width:88%;height:62%;display:flex;filter:drop-shadow(0 6px 14px rgba(0,0,0,.3))}
.tk .main{flex:1;background:#FBF8F0;border-radius:2cqw 0 0 2cqw;padding:2.6cqw 3.4cqw;display:flex;flex-direction:column;justify-content:space-between;
  -webkit-mask:radial-gradient(circle 2.2cqw at 100% 0,transparent 98%,#000) top/100% 51% no-repeat,radial-gradient(circle 2.2cqw at 100% 100%,transparent 98%,#000) bottom/100% 51% no-repeat;
          mask:radial-gradient(circle 2.2cqw at 100% 0,transparent 98%,#000) top/100% 51% no-repeat,radial-gradient(circle 2.2cqw at 100% 100%,transparent 98%,#000) bottom/100% 51% no-repeat}
.tk .stub{width:24%;background:#FBF8F0;border-radius:0 2cqw 2cqw 0;border-left:.4cqw dashed #CFC7B4;padding:2.6cqw 2.4cqw;display:flex;flex-direction:column;justify-content:space-between;
  -webkit-mask:radial-gradient(circle 2.2cqw at 0 0,transparent 98%,#000) top/100% 51% no-repeat,radial-gradient(circle 2.2cqw at 0 100%,transparent 98%,#000) bottom/100% 51% no-repeat;
          mask:radial-gradient(circle 2.2cqw at 0 0,transparent 98%,#000) top/100% 51% no-repeat,radial-gradient(circle 2.2cqw at 0 100%,transparent 98%,#000) bottom/100% 51% no-repeat}
.tk .lbl{font:600 2.4cqw var(--fm);color:#8A8272;letter-spacing:.06em}
.tk .route{display:flex;align-items:center;gap:2cqw}
.tk .route b{font:900 9cqw/1 var(--ft);color:#1C2128;letter-spacing:-.03em}
.tk .route .ln{flex:1;border-top:.4cqw dashed #B9B09C;position:relative}
.tk .route .ln::after{content:"✈";position:absolute;left:50%;top:-2.4cqw;font-size:3.6cqw;color:var(--accent);transform:translateX(-50%)}
.tk .row{display:flex;gap:3cqw;font:700 3.2cqw var(--fb)}
.tk .row span{display:block;font:600 2.2cqw var(--fm);color:#8A8272}
.tk .bc{height:9cqw;background:repeating-linear-gradient(90deg,#1C2128 0 .4cqw,transparent .4cqw .7cqw,#1C2128 .7cqw 1.4cqw,transparent 1.4cqw 1.7cqw,#1C2128 1.7cqw 1.9cqw,transparent 1.9cqw 2.5cqw)}
.tk .stamp{position:absolute;right:28%;bottom:10%;border:.5cqw solid var(--accent);color:var(--accent);border-radius:1cqw;padding:.6cqw 1.6cqw;font:800 4cqw var(--ft);transform:rotate(-12deg);opacity:0}
.play .d-ticket .tk{animation:slideIn .8s cubic-bezier(.2,1.2,.4,1) .2s both}
.play .d-ticket .stamp{animation:stamp .35s cubic-bezier(.3,1.6,.5,1) 1.3s both}
@keyframes slideIn{from{opacity:0;transform:translateX(-30%) rotate(-4deg)}to{opacity:1;transform:none}}
@keyframes stamp{from{opacity:0;transform:rotate(-12deg) scale(2)}to{opacity:.92;transform:rotate(-12deg) scale(1)}}

/* ── ④ 게임화 ── */
.d-game .qw{position:absolute;left:4%;bottom:5%;width:56%;background:#FFFDF6;border:.5cqw solid #2B2620;border-radius:1cqw;padding:2cqw 2.4cqw;font:700 3.2cqw/1.35 var(--fb);color:#2B2620;box-shadow:.8cqw .8cqw 0 rgba(43,38,32,.35)}
.d-game .qw .t{display:flex;justify-content:space-between;font:700 2.8cqw var(--fm);color:#7A6E5A}
.d-game .qw ul{list-style:none;margin:1cqw 0 1.4cqw;padding:0}
.d-game .qw li::before{content:"☐ ";color:#9A8F7C}
.d-game .qw li.ok::before{content:"☑ ";color:var(--g4)}
.d-game .qw li.nx::before{content:"☐ ";color:#9A8F7C}
.play .d-game .qw li.nx{animation:check .01s 1.8s both}
@keyframes check{to{color:var(--g4)}}
.d-game .xp{height:2cqw;border:.4cqw solid #2B2620;border-radius:99px;overflow:hidden;background:#EDE6D6}
.d-game .xp i{display:block;height:100%;width:40%;background:var(--g4)}
.play .d-game .xp i{animation:xp 1.2s cubic-bezier(.6,0,.3,1) .7s both}
@keyframes xp{from{width:40%}to{width:60%}}
.d-game .lv{position:absolute;right:6%;top:46%;background:var(--accent);color:#fff;font:800 5cqw var(--ft);padding:1cqw 2.4cqw;border-radius:1cqw;transform:rotate(4deg);opacity:0;box-shadow:.6cqw .6cqw 0 rgba(43,38,32,.35)}
.play .d-game .lv{animation:stamp2 .45s cubic-bezier(.3,1.7,.5,1) 2s both}
@keyframes stamp2{from{opacity:0;transform:rotate(4deg) scale(.3)}to{opacity:1;transform:rotate(4deg) scale(1)}}

/* ── ④ 물리 모션 ── */
.d-phys{background:#F6F4EF}
.d-phys .bins{position:absolute;left:4%;right:4%;bottom:5%;height:46%;display:grid;grid-template-columns:repeat(3,1fr);gap:2cqw}
.d-phys .bin{border:.4cqw solid #CFC8BC;border-top:0;border-radius:0 0 1.4cqw 1.4cqw;position:relative}
.d-phys .bin span{position:absolute;left:0;right:0;bottom:-0.2cqw;transform:translateY(100%);text-align:center;font:600 2.8cqw var(--fb);color:var(--sub)}
.d-phys .cd{position:absolute;width:24%;height:11%;border-radius:.8cqw;color:#fff;font:700 3cqw var(--fb);display:grid;place-items:center;box-shadow:0 2px 6px rgba(0,0,0,.18)}
.play .d-phys .cd{animation:drop 1s both;animation-delay:calc(var(--i)*.22s + .3s)}
@keyframes drop{0%{transform:translateY(-640%);opacity:0;animation-timing-function:cubic-bezier(.5,0,1,1)}10%{opacity:1}55%{transform:none;animation-timing-function:cubic-bezier(0,0,.5,1)}70%{transform:translateY(-38%);animation-timing-function:cubic-bezier(.5,0,1,1)}84%{transform:none;animation-timing-function:cubic-bezier(0,0,.5,1)}92%{transform:translateY(-10%)}100%{transform:none}}
.d-phys .cd.x{background:#9AA0A7!important;text-decoration:line-through}
.play .d-phys .cd.x{animation:bounceOut 1.6s both;animation-delay:1.7s}
@keyframes bounceOut{0%{transform:translate(0,-640%);opacity:0;animation-timing-function:cubic-bezier(.5,0,1,1)}8%{opacity:1}40%{transform:translate(0,0);animation-timing-function:cubic-bezier(0,0,.5,1)}70%{transform:translate(70%,-260%) rotate(18deg);animation-timing-function:cubic-bezier(.5,0,1,1)}100%{transform:translate(110%,-150%) rotate(28deg);opacity:.85}}

/* ── ⑤ 키네틱 타이포 ── */
.d-kin{background:#1E2329;display:flex;flex-direction:column;justify-content:center;padding:0 9%}
.d-kin .w{font:900 17cqw/1.05 var(--ft);color:#fff;letter-spacing:-.04em;white-space:nowrap}
.d-kin .w span{display:inline-block}
.play .d-kin .w span{animation:letter .7s cubic-bezier(.2,1.6,.4,1) both;animation-delay:calc(var(--i)*.12s + .2s)}
@keyframes letter{from{opacity:0;transform:translateY(-70%) rotate(-14deg)}to{opacity:1;transform:none}}
.d-kin .w .hl{color:#FFB48A}
.d-kin .ul{height:1.2cqw;background:var(--accent);margin-top:2cqw;transform-origin:left;transform:scaleX(0)}
.play .d-kin .ul{animation:ul .6s cubic-bezier(.7,0,.2,1) 1.3s forwards}
@keyframes ul{to{transform:scaleX(1)}}
.d-kin .s{font:500 4cqw var(--fb);color:#AEB4BB;margin-top:2.4cqw;opacity:0}
.play .d-kin .s{animation:fadeIn .5s 1.8s both}

/* ── ⑤ 재질·질감 ── */
.d-tex .strip{position:absolute;left:8%;top:30%;background:#FBF6E8;padding:2cqw 3.4cqw;font:900 8.6cqw/1.05 var(--ft);color:#2E4A2E;transform:rotate(-2.5deg);box-shadow:0 3px 8px rgba(0,0,0,.22);clip-path:polygon(0 3%,4% 0,30% 4%,58% 0,82% 3%,100% 0,98% 50%,100% 97%,70% 100%,40% 96%,12% 100%,0 96%,2% 50%)}
.d-tex .strip2{position:absolute;left:12%;top:60%;background:#E9D9B5;padding:1.2cqw 2.6cqw;font:700 4.2cqw var(--fb);color:#4B3A20;transform:rotate(1.5deg);box-shadow:0 2px 6px rgba(0,0,0,.2)}
.d-tex .tape{position:absolute;width:13%;height:6%;background:rgba(242,226,170,.78);left:5%;top:26%;transform:rotate(-30deg);box-shadow:0 1px 2px rgba(0,0,0,.12)}
.play .d-tex .strip{animation:place .6s cubic-bezier(.2,1.4,.4,1) .3s both}
.play .d-tex .strip2{animation:place .6s cubic-bezier(.2,1.4,.4,1) .7s both}
.play .d-tex .tape{animation:fadeIn .3s 1.1s both}
@keyframes place{from{opacity:0;transform:translateY(-18%) rotate(-8deg) scale(1.08)}}

/* ── ⑤ 3D·깊이 ── */
.d-3d{background:linear-gradient(#F6F4EF,#E7E3DB);perspective:120cqw}
.d-3d .stk{position:absolute;left:30%;top:56%;width:40cqw;height:40cqw;transform-style:preserve-3d;transform:translate(-50%,-50%) rotateX(60deg) rotateZ(-38deg)}
.d-3d .ly{position:absolute;inset:0;border-radius:1.4cqw;border:.3cqw solid rgba(255,255,255,.7);background:var(--c);opacity:.86;transform:translateZ(calc(var(--i)*5.2cqw))}
.play .d-3d .ly{animation:stack .7s cubic-bezier(.3,1.4,.5,1) both;animation-delay:calc(var(--i)*.38s + .3s)}
@keyframes stack{from{opacity:0;transform:translateZ(calc(var(--i)*5.2cqw + 30cqw))}to{opacity:.86}}
.d-3d .goal{position:absolute;inset:-14%;border:.4cqw dashed var(--accent);border-radius:1.6cqw;background:rgba(226,87,26,.07);transform:translateZ(13cqw)}
.d-3d .n{position:absolute;right:6%;top:10%;text-align:right;font:600 3.4cqw var(--fb);color:var(--sub)}
.d-3d .n b{display:block;font:900 12cqw/1 var(--ft);color:var(--ink);letter-spacing:-.04em}
.d-3d .n b em{font-style:normal;color:var(--accent)}
.d-3d .gl{position:absolute;right:6%;top:52%;font:700 3.2cqw var(--fb);color:var(--accent)}

/* ── ⑤ 극단적 여백 ── */
.d-blank .tt{position:absolute;left:6%;top:9%;font:800 6.4cqw/1.15 var(--ft);color:var(--ink);letter-spacing:-.03em;opacity:0}
.d-blank .tt small{display:block;font:500 3.2cqw var(--fb);color:var(--sub);margin-top:1.4cqw;letter-spacing:0}
.play .d-blank .tt{animation:fadeIn 1.2s .4s both}


/* ── ⑥ 팡! 터뜨리기: 캔버스 입자 불꽃 ── */
.fw{position:absolute;inset:0;overflow:hidden;container-type:size;background:#03050A}
.fw .fwbg{position:absolute;inset:0;background-image:var(--img-N),radial-gradient(120% 90% at 50% 100%,#16223C 0%,#070B16 55%,#020308 100%);background-size:cover,100% 100%;background-position:center bottom,center}
.fw canvas{position:absolute;inset:0;width:100%;height:100%}
.fw canvas.gl{filter:blur(.7cqw) brightness(1.15);opacity:.55;mix-blend-mode:screen}
.fw .fwt{position:absolute;left:0;right:0;top:60%;transform:translateY(-50%);text-align:center;opacity:0;transition:opacity .9s ease;pointer-events:none}
.fw .fwt.on{opacity:1}
.fw .fwt b{display:inline-block;font:400 6cqw/1 var(--ft);letter-spacing:.2em;margin-right:-.2em;color:#F6F4EF;white-space:nowrap;text-shadow:0 0 1.2cqw rgba(255,255,255,.28)}
.fw .fwt span{position:absolute;left:0;right:0;top:100%;display:block;margin-top:2.2cqw;font:500 max(1.2cqw,9px) var(--fb);color:rgba(246,244,239,.62);letter-spacing:.42em;padding-left:.42em}
.demo .fw .fwt b{font-size:10cqw}
.fullbtn{position:absolute;right:3%;top:3%;z-index:3;font:600 13px var(--fb);color:#fff;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.4);border-radius:99px;padding:6px 12px;cursor:pointer}
.fullbtn:hover{background:rgba(255,255,255,.26)}
.fullv{position:absolute;inset:0;z-index:40;display:none;background:#020308}
.fullv [data-kind]{display:none}
.fullv [data-kind].on{display:block}
.cv3{position:absolute;inset:0;container-type:size;background:#0D0C0E}
.cv3 canvas{position:absolute;inset:0;width:100%;height:100%}
.asm{position:absolute;inset:0;background:#0B0E12;container-type:size}
.asm canvas{position:absolute;inset:0;width:100%;height:100%}
.fullv.open{display:block}
.fvtag{position:absolute;left:28px;top:22px;z-index:3;font:600 15px var(--fm);color:rgba(255,255,255,.72)}
.fvbar{position:absolute;right:24px;bottom:20px;z-index:3;display:flex;gap:8px}
.fvbar button{font:600 15px var(--fb);color:#fff;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.32);border-radius:8px;padding:9px 16px;cursor:pointer}
.fvbar button:hover{background:rgba(255,255,255,.24)}

/* ── ⑥ 또롱또롱 떨어지기 ── */
.d-drop{background:linear-gradient(#F3F8FB 0 66%,#CFE3EE 66%,#B6D3E3)}
.d-drop .surf{position:absolute;left:0;right:0;top:66%;height:.4cqw;background:#9CC3D8}
.d-drop .dp{position:absolute;top:-8%;width:4.4cqw;height:4.4cqw;margin-left:-2.2cqw;background:#4F9CC4;border-radius:0 50% 50% 50%;transform:rotate(45deg);opacity:0}
.play .d-drop .dp{animation:fall .55s cubic-bezier(.55,0,1,.45) both;animation-delay:calc(var(--i)*.6s + .3s)}
@keyframes fall{0%{opacity:1;transform:translateY(0) rotate(45deg)}99%{opacity:1;transform:translateY(68cqh) rotate(45deg)}100%{opacity:0;transform:translateY(68cqh) rotate(45deg)}}
.d-drop .rp{position:absolute;top:66%;width:16cqw;height:4.4cqw;margin:-2.2cqw 0 0 -8cqw;border:.5cqw solid #4F9CC4;border-radius:50%;opacity:0}
.play .d-drop .rp{animation:ripple 1.1s ease-out both;animation-delay:calc(var(--i)*.6s + .85s)}
.play .d-drop .rp.r2{animation-delay:calc(var(--i)*.6s + 1.05s)}
@keyframes ripple{0%{opacity:.9;transform:scale(.15)}100%{opacity:0;transform:scale(1.4)}}
.d-drop .lb{position:absolute;top:44%;transform:translateX(-50%);opacity:0}
.d-drop .lb b{display:block;padding:1.2cqw 2.4cqw;border-radius:99px;background:#fff;color:#1F5E80;font:800 4.4cqw var(--ft);box-shadow:0 3px 10px -4px rgba(31,94,128,.5);white-space:nowrap}
.play .d-drop .lb{animation:lbIn .5s cubic-bezier(.2,1.6,.4,1) both;animation-delay:calc(var(--i)*.6s + .86s)}
@keyframes lbIn{from{opacity:0;transform:translate(-50%,40%) scale(.5)}to{opacity:1;transform:translate(-50%,0)}}
.d-drop .tt{position:absolute;top:28%;transform:translateX(-50%);font:800 4.6cqw var(--ft);color:#4F9CC4;opacity:0;white-space:nowrap}
.play .d-drop .tt{animation:ono2 .8s both;animation-delay:calc(var(--i)*.6s + .84s)}
@keyframes ono2{0%{opacity:0;transform:translate(-50%,2cqw)}30%{opacity:1}100%{opacity:0;transform:translate(-50%,-3cqw)}}
.d-drop .cap{position:absolute;left:0;right:0;bottom:8%;text-align:center;font:600 3.6cqw var(--fb);color:#1F5E80;opacity:0}
.play .d-drop .cap{animation:fadeIn .5s 3.3s both}

/* ── 9 고르는 법 ── */
.pick{position:absolute;left:64px;top:232px;width:860px;bottom:62px;background:var(--surface);border-radius:14px;padding:26px 30px}
.pick h3,.rules h3{margin:0 0 14px;font:800 26px var(--ft)}
.pick table{width:100%;border-collapse:collapse;font:500 16px/1.35 var(--fb)}
.pick th{text-align:left;font:600 14px var(--fm);color:var(--sub);padding:0 0 8px;border-bottom:2px solid var(--ink)}
.pick td{padding:4px 0;border-bottom:1px solid var(--line);vertical-align:top}
.pick td:first-child{font-weight:700;width:46%;padding-right:20px}
.pick .tg{display:inline-block;margin:0 5px 3px 0;padding:2px 9px;border-radius:99px;font:600 14px var(--fb);color:#fff;background:var(--gc)}
.rules{position:absolute;left:950px;right:64px;top:232px;bottom:62px;display:flex;flex-direction:column;gap:14px}
.rules ol{margin:0;padding:0;list-style:none;display:grid;gap:12px;counter-reset:r}
.rules li{background:var(--surface);border-radius:12px;padding:16px 20px 16px 64px;position:relative;font:400 16px/1.5 var(--fb);color:#3A4049;counter-increment:r}
.rules li::before{content:counter(r);position:absolute;left:18px;top:16px;width:32px;height:32px;border-radius:50%;background:var(--ink);color:#fff;display:grid;place-items:center;font:700 16px var(--fm)}
.rules li b{display:block;font:700 19px var(--fb);color:var(--ink);margin-bottom:2px}
.rules li:first-child::before{background:var(--accent)}
.rules .off{margin-top:auto;border:1.5px dashed #B9B3A8;border-radius:12px;padding:14px 20px;font:400 15px/1.5 var(--fb);color:var(--sub)}
.rules .off b{color:var(--ink)}

/* 인쇄: 한 장 = 한 쪽, 움직임은 끝 화면으로 */
@page{size:1600px 900px;margin:0}
/* ── ⑦ 흐름 띠: 띠가 왼쪽부터 차례로 흘러가고, 가장 굵은 띠만 진한 색 ── */
.d-flow{background:#fff}
.d-flow svg{position:absolute;inset:4% 3%;width:94%;height:92%}
.d-flow text{font:600 13px var(--fb);fill:#1C2128}
.d-flow .tl{font:800 15px var(--ft)}
.d-flow .note{font:500 12px var(--fb);fill:#5C636C}
.d-flow .bd{opacity:.95}
.play .d-flow .bd{animation:flowIn .9s cubic-bezier(.5,0,.2,1) both;animation-delay:calc(var(--i)*.45s + .4s)}
.play .d-flow .rn,.play .d-flow .lb{animation:fadeIn .4s both;animation-delay:calc(var(--i)*.45s + 1.1s)}
@keyframes flowIn{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}

/* ── ⑦ 점 다시 모으기(JS: regroup) ── */
.d-regroup{background:#fff}
.d-regroup .dot{position:absolute;width:5cqw;height:5cqw;margin:-2.5cqw 0 0 -2.5cqw;border-radius:50%;background:#C9CED4;transition:left .9s cubic-bezier(.6,0,.2,1),top .9s cubic-bezier(.6,0,.2,1),background .5s}
.d-regroup .lab{position:absolute;bottom:7%;transform:translateX(-50%);font:600 4.4cqw var(--fb);color:#5C636C;opacity:0;transition:opacity .5s}
.d-regroup .lab b{font:900 7cqw var(--ft);color:#1C2128;margin-left:.8cqw}
.d-regroup .cap{position:absolute;left:6%;top:5%;font:700 4.6cqw var(--fb);color:#1C2128}
.d-regroup.grouped .lab{opacity:1}

/* ── ⑦ 시선 넘기기: 강조 틀이 한 칸씩 내려가고 나머지는 흐려진다. 끝나면 모두 밝게 ── */
.d-hand{background:#fff}
.d-hand .row{position:absolute;left:8%;right:8%;height:17%;top:calc(8% + var(--i)*22%);display:grid;grid-template-columns:9cqw 1fr;grid-template-rows:auto auto;align-content:center;column-gap:3cqw;font:800 6.6cqw/1.15 var(--ft);color:#1C2128}
.d-hand .row b{grid-row:1 / 3;display:grid;place-items:center;width:9cqw;height:9cqw;border-radius:50%;background:#EEF4F5;color:var(--g7);font:700 4.6cqw var(--fm)}
.d-hand .row span{font:500 4cqw var(--fb);color:#5C636C}
.d-hand .box{position:absolute;left:4%;right:4%;height:20%;top:6.5%;border:.8cqw solid var(--g7);border-radius:2cqw;opacity:0}
.play .d-hand .box{animation:handBox 5.4s cubic-bezier(.6,0,.2,1) .3s both}
.play .d-hand .row:nth-of-type(2){animation:hand0 5.4s .3s both}.play .d-hand .row:nth-of-type(3){animation:hand1 5.4s .3s both}
.play .d-hand .row:nth-of-type(4){animation:hand2 5.4s .3s both}.play .d-hand .row:nth-of-type(5){animation:hand3 5.4s .3s both}
@keyframes handBox{0%{opacity:0;top:6.5%}4%,20%{opacity:1;top:6.5%}25%,41%{opacity:1;top:28.5%}46%,62%{opacity:1;top:50.5%}67%,86%{opacity:1;top:72.5%}100%{opacity:0;top:72.5%}}
@keyframes hand0{0%,20%{opacity:1}24%,86%{opacity:.28}100%{opacity:1}}
@keyframes hand1{0%,20%{opacity:.28}24%,41%{opacity:1}45%,86%{opacity:.28}100%{opacity:1}}
@keyframes hand2{0%,41%{opacity:.28}45%,62%{opacity:1}66%,86%{opacity:.28}100%{opacity:1}}
@keyframes hand3{0%,62%{opacity:.28}66%,100%{opacity:1}}

/* ── ⑦ 한 바퀴 돌기: 고리가 시계 방향으로 차고, 달마다 점이 켜진다 ── */
.d-clock{background:#fff}
.d-clock .ring{position:absolute;left:50%;top:50%;width:62cqw;height:62cqw;margin:-31cqw 0 0 -31cqw;border-radius:50%;--a:360deg;
  background:conic-gradient(var(--g7) var(--a),#E6E2DA 0);-webkit-mask:radial-gradient(closest-side,transparent 78%,#000 79%);mask:radial-gradient(closest-side,transparent 78%,#000 79%)}
.play .d-clock .ring{animation:clockA 3.6s linear .5s both}
@keyframes clockA{from{--a:0deg}to{--a:360deg}}
.d-clock .m{position:absolute;left:50%;top:50%;width:0;height:0;transform:rotate(var(--r)) translateY(-40cqw)}
.d-clock .m span{position:absolute;left:-3.6cqw;top:-3.6cqw;width:7.2cqw;height:7.2cqw;display:grid;place-items:center;border-radius:50%;transform:rotate(calc(var(--r) * -1));font:700 3.6cqw var(--fm);background:var(--g7);color:#fff}
.play .d-clock .m span{animation:monthOn .3s both;animation-delay:calc(var(--i)*.3s + .5s)}
@keyframes monthOn{from{background:#E6E2DA;color:#9AA0A7}to{background:var(--g7);color:#fff}}
.d-clock .mid{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);text-align:center}
.d-clock .mid > *{display:block}
.d-clock .mid .a{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font:800 9cqw var(--ft);color:#5C636C;opacity:0;white-space:nowrap}
.d-clock .mid b{font:900 15cqw/1 var(--ft);color:#1C2128;letter-spacing:-.04em}
.d-clock .mid small{margin-top:1.4cqw;font:600 3.8cqw var(--fb);color:var(--g7);white-space:nowrap}
.play .d-clock .mid .a{animation:clockStart 4.1s both}
.play .d-clock .mid .z{animation:fadeIn .5s 4.1s both}
@keyframes clockStart{0%,85%{opacity:1}100%{opacity:0}}

/* ── ⑧ 출발판 넘김(JS: flap) ── */
.d-flap{background:#1E2329;padding:5% 6%;display:flex;flex-direction:column;justify-content:center}
.d-flap .hd{display:flex;justify-content:space-between;font:600 3.6cqw var(--fm);color:#AEB4BB;border-bottom:1px solid #39404A;padding-bottom:2cqw}
.d-flap .fr{display:flex;align-items:center;justify-content:space-between;margin-top:4cqw}
.d-flap .k{font:700 5.2cqw var(--fb);color:#fff;white-space:nowrap}
.d-flap .cells{display:flex;gap:1cqw}
.d-flap .c{position:relative;width:9.6cqw;height:13cqw;display:grid;place-items:center;border-radius:1cqw;background:#2E343C;font:800 8.4cqw/1 var(--ft);color:#F4F1E8}
.d-flap .c::after{content:"";position:absolute;left:0;right:0;top:50%;height:2px;background:#1E2329}
.d-flap .c.f{animation:flapTick .07s linear}
.d-flap .c.end{color:#E9F07A}
@keyframes flapTick{0%{transform:scaleY(1)}50%{transform:scaleY(.15)}100%{transform:scaleY(1)}}

/* ── ⑧ 동그라미 치기: 펜 선이 숫자를 두르고 손글씨 한마디 ── */
.d-circle{background:#fff}
.d-circle table{position:absolute;left:8%;width:84%;top:14%;border-collapse:collapse;font:500 5cqw/1 var(--fb);color:#1C2128}
.d-circle th{font:600 3.8cqw var(--fm);color:#5C636C;text-align:right;padding:0 2cqw 2.4cqw;border-bottom:2px solid #1C2128}
.d-circle th:first-child,.d-circle td:first-child{text-align:left}
.d-circle td{text-align:right;padding:3.4cqw 2cqw;border-bottom:1px solid #E6E2DA}
.d-circle td b{font-weight:800}
.d-circle .hit{position:relative;font-weight:800}
.d-circle svg{position:absolute;left:50%;top:50%;width:24cqw;height:14.4cqw;transform:translate(-56%,-52%);overflow:visible}
.d-circle path{fill:none;stroke:var(--g8);stroke-width:3.6;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:1;stroke-dashoffset:0}
.play .d-circle path{animation:penDraw 1.1s cubic-bezier(.5,.1,.3,1) .8s both}
@keyframes penDraw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
.d-circle .memo{position:absolute;right:6%;bottom:9%;font:400 8.6cqw/1 "Nanum Pen Script",cursive;color:var(--g8);transform:rotate(-6deg)}
.play .d-circle .memo{animation:fadeIn .4s 2s both}

/* ── ⑧ 카드 뒤집기: 질문 면이 차례로 뒤집혀 답 ── */
.d-flip{background:#F1EEE8;display:grid;grid-template-columns:repeat(3,1fr);column-gap:3%;padding:9% 5%;perspective:900px}
.d-flip .fc{position:relative;transform-style:preserve-3d;transform:rotateY(180deg)}
.play .d-flip .fc{animation:flipCard .8s cubic-bezier(.5,0,.2,1) both;animation-delay:calc(var(--i)*.9s + 1.4s)}
@keyframes flipCard{from{transform:none}to{transform:rotateY(180deg)}}
.d-flip .f,.d-flip .b{position:absolute;inset:0;border-radius:2cqw;backface-visibility:hidden;-webkit-backface-visibility:hidden;display:flex;flex-direction:column;padding:4cqw 3cqw}
.d-flip .f{background:#fff;font:700 4.4cqw/1.35 var(--fb);color:#1C2128;box-shadow:0 1px 0 #DAD5CC}
.d-flip .f span{font:800 9cqw/1 var(--ft);color:var(--g8);margin-bottom:3cqw}
.d-flip .b{background:var(--g8);color:#fff;transform:rotateY(180deg);justify-content:center;align-items:center;text-align:center}
.d-flip .b b{font:900 14cqw/1 var(--ft);letter-spacing:-.04em}
.d-flip .b b small{font-size:.4em;margin-left:.5cqw}
.d-flip .b span{margin-top:2.4cqw;font:600 3.6cqw var(--fb);opacity:.85}

/* ── ⑨ 줌 스루: "2026"의 0(빈 고리)으로 들어가 → 겹친 고리를 지나 → "2027"(0이 꽉 찬 원). 그림 없이 글자 · 도형만 ──
   16:9 틀(.fr)이 데모 상자를 덮고 틀 자신이 컨테이너라, 안의 cqw 는 틀 폭 기준(상자 비율이 달라도 위치가 같다).
   숫자 4칸은 고정폭 14cqw, 첫 칸이 x 22cqw → 0 칸 중심은 x 43%, y 50%. 끝 모습(움직임 줄이기 · 인쇄)은 2027 장면 */
.d-thru{background:#A8323E;overflow:hidden}
.d-thru .fr{position:absolute;left:50%;top:50%;width:max(100cqw,177.78cqh);height:max(56.25cqw,100cqh);translate:-50% -50%;container-type:size}
.d-thru .la,.d-thru .lc,.d-thru .lz{position:absolute;inset:0}
.d-thru .num{position:absolute;left:22cqw;top:50%;translate:0 -50%;display:flex}
.d-thru .cl{position:relative;width:14cqw;height:20cqw;display:grid;place-items:center}
.d-thru .cl b{font:900 21cqw/1 var(--ft);letter-spacing:-.04em}
.d-thru .cl i{display:block;width:11.6cqw;height:16.4cqw;border-radius:50%;box-sizing:border-box}
.d-thru .tg{position:absolute;left:22cqw;top:calc(50% - 16.5cqw);margin:0;font:800 3.8cqw var(--fb);letter-spacing:.06em}
/* 올해: 크림 바탕에 먹 숫자, 0 은 붉은 빈 고리. 고리 안쪽만 뚫려 있어 그 너머 고리들이 보인다 */
.d-thru .la{background:#F6EFE0;color:#1C2128;transform-origin:43% 50%;opacity:0;
  -webkit-mask:radial-gradient(ellipse 2.4cqw 4.8cqw at 43% 50%,transparent 97%,#000 100%);mask:radial-gradient(ellipse 2.4cqw 4.8cqw at 43% 50%,transparent 97%,#000 100%)}
.d-thru .la .tg{color:#A8323E}
.d-thru .ring{border:3.4cqw solid #A8323E}
/* 고리 너머: 같은 중심의 원 여섯 겹(먹 · 크림 · 붉은색). 가장 안쪽 붉은 원이 2027 장면의 바탕이 된다 */
.d-thru .sky{position:absolute;left:50%;top:50%;width:0;height:0;transform-origin:0 0;scale:1}
.d-thru .sky i{position:absolute;width:var(--d);height:var(--d);margin:calc(var(--d) / -2) 0 0 calc(var(--d) / -2);border-radius:50%;background:var(--c)}
.d-thru .lc{opacity:0}
/* 내년: 붉은 바탕에 크림 숫자, 0 은 노란 꽉 찬 원 */
.d-thru .lz{color:#F6EFE0}
.d-thru .lz .tg{color:#F5C518}
.d-thru .dot{background:#F5C518;box-shadow:0 0 0 .5cqw #F6EFE0 inset}
.d-thru .sb{position:absolute;left:22cqw;top:calc(50% + 11.5cqw);margin:0;font:800 4.4cqw var(--ft);letter-spacing:-.01em}
.play .d-thru .la{animation:thA 5.6s both}
.play .d-thru .la .cl{animation:digUp .55s cubic-bezier(.25,1.6,.45,1) both;animation-delay:calc(var(--i) * .09s + .15s)}
.play .d-thru .la .tg{animation:fadeIn .4s .6s both}
.play .d-thru .lc{animation:thC 5.6s both}
.play .d-thru .sky{animation:thSky 5.6s both}
.play .d-thru .lz{animation:thZ 5.6s both}
.play .d-thru .lz .cl{animation:digDrop .6s cubic-bezier(.25,1.6,.45,1) both;animation-delay:calc(var(--i) * .1s + 3.15s)}
.play .d-thru .lz .dot{animation:dotFill .5s cubic-bezier(.3,1.8,.5,1) 3.6s both}
.play .d-thru .lz .tg{animation:fadeIn .4s 3.1s both}
.play .d-thru .lz .sb{animation:fadeUp .5s 3.85s both}
@keyframes digUp{from{opacity:0;transform:translateY(60%)}to{opacity:1;transform:none}}
@keyframes digDrop{from{opacity:0;transform:translateY(-70%)}to{opacity:1;transform:none}}
@keyframes dotFill{from{transform:scale(.2)}to{transform:none}}
/* 0 의 구멍으로: 0 을 틀 가운데로 옮기며 28배(가속). 구멍이 화면을 덮는 순간 '올해'를 내리고 고리 장면만 남긴다 */
@keyframes thA{
  0%,21%{opacity:1;transform:none;animation-timing-function:ease-in-out}
  27%{opacity:1;transform:scale(.965);animation-timing-function:cubic-bezier(.62,0,.94,.36)}
  47%{opacity:1;transform:translate(7%,0) scale(28)}
  47.01%,100%{opacity:0;transform:translate(7%,0) scale(28)}}
@keyframes thC{0%{opacity:1}57%{opacity:1}57.01%,100%{opacity:0}}
/* 고리: 구멍 너머로 작게 보이다(0.16배) 구멍이 열리면서 커지고, 이어서 한 겹씩 지나간다(9배) */
@keyframes thSky{
  0%,27%{scale:.16;translate:-7cqw 0;animation-timing-function:cubic-bezier(.62,0,.94,.36)}
  47%{scale:1;translate:0 0;animation-timing-function:cubic-bezier(.45,0,.9,.5)}
  62%,100%{scale:9;translate:0 0}}
@keyframes thZ{0%,56.9%{opacity:0}57%,100%{opacity:1}}

/* ── ⑨ 사선 패널 교체: 같은 기울기의 판이 왼쪽에서 쓸고 지나가며 다음 담당(앞 가장자리에 노란 띠) → 끝에 사선 기둥 셋으로 나란히 ──
   판 · 띠 모두 clip-path 다각형 보간이라 상자 비율이 달라도 가장자리가 딱 맞는다. 판 k 는 0.15 + 1.85k 초에 쓸려 들어오고, 5.7초에 셋이 함께 기둥(--col)으로 */
.d-slash{background:#F6EFE0;color:#fff;word-break:keep-all}
.d-slash .pn{position:absolute;inset:0;background:var(--c);clip-path:polygon(0 0,0 0,-30% 100%,-30% 100%)}
.d-slash .eg{position:absolute;inset:0;background:#F5C518;clip-path:polygon(-1.8% 0,0 0,-30% 100%,-31.8% 100%);z-index:1}
.d-slash .fc{position:absolute;left:8%;top:0;bottom:0;right:8%;display:flex;flex-direction:column;justify-content:center;gap:2.4cqh}
.d-slash .fc em{position:absolute;right:0;top:6%;font:900 46cqh/1 var(--ft);font-style:normal;letter-spacing:-.05em;color:rgba(255,255,255,.12)}
.d-slash .fc span{font:700 6.2cqh var(--fb);color:#F5C518;letter-spacing:.02em}
.d-slash .fc b{font:900 14cqh/1.1 var(--ft);letter-spacing:-.04em}
.d-slash .fc p{margin:2cqh 0 0;display:flex;align-items:baseline;gap:1.4cqw;font:700 6.2cqh var(--fb)}
.d-slash .fc p i{font-style:normal;opacity:.85}
.d-slash .fc p strong{font:900 12cqh/1 var(--ft);color:#F5C518;letter-spacing:-.03em}
.d-slash .fc p small{font-size:6.2cqh;opacity:.85}
.d-slash .cc{position:absolute;top:0;bottom:0;left:calc(var(--k) * 33.333% + 6%);width:24%;display:flex;flex-direction:column;justify-content:center;gap:1.6cqh;opacity:0}
.d-slash .cc em{font:900 16cqh/1 var(--ft);font-style:normal;color:#F5C518;letter-spacing:-.04em}
.d-slash .cc span{font:700 6.2cqh var(--fb);opacity:.9}
.d-slash .cc b{font:900 7.2cqh/1.18 var(--ft);letter-spacing:-.03em}
.d-slash .tb{position:absolute;left:8%;bottom:7%;display:flex;gap:1cqw;z-index:2}
.d-slash .tb i{display:block;width:5cqw;height:1.4cqh;transform:skewX(-28deg);box-shadow:inset 0 0 0 .3cqh rgba(255,255,255,.7)}
.play .d-slash .pn{animation:slSweep .7s cubic-bezier(.65,0,.25,1) both,slCol .8s cubic-bezier(.65,0,.25,1) 5.45s forwards;animation-delay:calc(var(--k) * 1.85s + .15s),5.45s}
.play .d-slash .eg{animation:slEdge .7s cubic-bezier(.65,0,.25,1) both;animation-delay:calc(var(--k) * 1.85s + .15s)}
.play .d-slash .fc > *{animation:slIn .55s cubic-bezier(.2,.8,.2,1) both,fadeOutK .25s 5.4s forwards;animation-delay:calc(var(--k) * 1.85s + .55s),5.4s}
.play .d-slash .fc span{animation-delay:calc(var(--k) * 1.85s + .5s),5.4s}
.play .d-slash .fc b{animation-delay:calc(var(--k) * 1.85s + .6s),5.4s}
.play .d-slash .fc p{animation-delay:calc(var(--k) * 1.85s + .75s),5.4s}
.play .d-slash .fc em{animation-delay:calc(var(--k) * 1.85s + .45s),5.4s}
.play .d-slash .cc{animation:slColIn .5s cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(var(--k) * .12s + 5.95s)}
.play .d-slash .tb{animation:fadeOutK .3s 5.4s forwards}
.play .d-slash .tb i{animation:slTab .3s both}
.play .d-slash .tb i:nth-child(1){animation-delay:.6s}.play .d-slash .tb i:nth-child(2){animation-delay:2.45s}.play .d-slash .tb i:nth-child(3){animation-delay:4.3s}
@keyframes slSweep{from{clip-path:polygon(0 0,0 0,-30% 100%,-30% 100%)}to{clip-path:polygon(0 0,140% 0,110% 100%,-30% 100%)}}
@keyframes slEdge{from{clip-path:polygon(-1.8% 0,0 0,-30% 100%,-31.8% 100%)}to{clip-path:polygon(138.2% 0,140% 0,110% 100%,108.2% 100%)}}
@keyframes slCol{from{clip-path:polygon(0 0,140% 0,110% 100%,-30% 100%)}to{clip-path:var(--col)}}
@keyframes slIn{from{opacity:0;transform:translateX(-5cqw)}to{opacity:1;transform:none}}
@keyframes slColIn{from{opacity:0;transform:translateY(4cqh)}to{opacity:1;transform:none}}
@keyframes slTab{from{background:transparent}to{background:#F5C518}}
@keyframes fadeOutK{to{opacity:0}}

/* ── ⑨ 선이 모여 줌(네 번째 판, 2026-11-28 승인된 멈춘 장면 세 장을 잇는다) ──
   ① 사람이 꼬불꼬불한 점선 길로 일곱 곳을 돈다(길은 마스크로 걸은 만큼만 보이고, 닿을 때마다 번호) ② 같은 일곱 점이 원 둘레로 모이고 원 · 점선
   ③ 원(rect)이 늘어나 통합지원센터 판, 일곱 점은 판 안 칩 자리로(크기 · 색이 바뀜), 사람은 화살표 하나로.
   일곱 점은 한 요소가 처음부터 끝까지 움직인다(.nd = 원점에 그리고 transform 으로 자리). 16:9 틀(.fr)은 상자 안에 맞춘다. 끝 모습은 장면 3 */
.d-conv{background:#F6EFE0;overflow:hidden}
.d-conv .fr{position:absolute;left:50%;top:50%;width:min(100cqw,177.78cqh);height:min(56.25cqw,100cqh);translate:-50% -50%;container-type:size}
.d-conv svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible;font-family:var(--ft)}
.d-conv .way{fill:none;stroke:#A8323E;stroke-width:7;stroke-dasharray:2 22;stroke-linecap:round}
.d-conv .wm{fill:none;stroke:#fff;stroke-width:40;stroke-dasharray:1;stroke-dashoffset:0}
.d-conv .nd circle{fill:#1C2128}
.d-conv .nd .ic{stroke:#F6EFE0}
.d-conv .nd text{font-weight:800;font-size:42px;fill:#1C2128;text-anchor:middle;transform-box:fill-box;transform-origin:center}
.d-conv .bd circle{fill:#A8323E}.d-conv .bd text{font-weight:900;font-size:26px;fill:#F6EFE0;text-anchor:middle}
.d-conv .walker,.d-conv .me{fill:#1C2128}.d-conv .walker{fill:#A8323E}
.d-conv .sp path{stroke:#1C2128;stroke-width:8;stroke-linecap:round;stroke-dasharray:1 18}
.d-conv .hub{fill:#A8323E;x:860px;y:340px;width:300px;height:300px;rx:150px;transform-box:fill-box;transform-origin:center}
.d-conv .hub-t{font-weight:900;font-size:66px;fill:#F6EFE0;text-anchor:middle}
.d-conv .box-t{font-weight:900;font-size:66px;fill:#F6EFE0}
.d-conv .box-s{font-weight:700;font-size:37px;fill:#F5C518}
.d-conv .ar{fill:none;stroke:#1C2128;stroke-width:10;stroke-linecap:round;stroke-dasharray:1}
.d-conv .ah{fill:none;stroke:#1C2128;stroke-width:10;stroke-linecap:round}
.d-conv .t{position:absolute;left:5cqw;top:7.8cqh}
.d-conv .kk{font:800 2.4cqw var(--ft);color:#A8323E;letter-spacing:.04em}
.d-conv h2{margin:1.5cqh 0 0;font:900 4.9cqw/1.15 var(--ft);color:#1C2128;letter-spacing:-.03em}
.d-conv h2 b{color:#A8323E}.d-conv h2 b.big{display:block;font-size:7.5cqw}
/* 시간표(초): 점 0.3 · 걷기 0.6~3.5 · 장면 2 3.8 · 원 4.3 · 점선 4.7 · 장면 3 5.8 · 판 글자 6.6 · 사람 7.0 */
.play .d-conv .wm{animation:cvWalkM 2.9s linear .6s both}
.play .d-conv .walker{animation:cvWalk 2.9s linear .6s both,cvOut .3s 3.8s forwards}
.play .d-conv .way{animation:cvOut .4s 3.8s forwards}
.play .d-conv .bd{animation:cvPop .35s cubic-bezier(.3,1.8,.5,1) both,cvOut .3s 3.8s forwards;animation-delay:var(--t),3.8s;transform-box:fill-box;transform-origin:center}
.play .d-conv .hub{animation:cvHub 8s both}
.play .d-conv .hub-t{animation:cvHubT 8s both}
.play .d-conv .sp path{animation:cvSp 8s both}
.play .d-conv .box-t,.play .d-conv .box-s{animation:fadeUp .5s 6.6s both}
.play .d-conv .box-s{animation-delay:6.8s}
.play .d-conv .ar{animation:penDraw .45s cubic-bezier(.4,0,.2,1) 7.05s both}
.play .d-conv .ah{animation:fadeIn .2s 7.45s both}
.play .d-conv .me{animation:cvMe .55s cubic-bezier(.2,.8,.3,1.2) 6.9s both}
.play .d-conv .nd circle{animation:cvNc 8s both}
.play .d-conv .nd .ic{animation:cvNi 8s both}
.play .d-conv .t1{animation:cvOut .35s 3.75s forwards}
.play .d-conv .t1 > *{animation:fadeUp .5s .1s both}
.play .d-conv .t2{animation:cvT2 8s both}
.play .d-conv .t3{animation:cvT3 8s both}
