/* ── ⑨ 카드 더미 펼치기: 흩어진 카드 → 한 묶음 → 부채 ── */
.d-fan{background:#F1EEE8}
.d-fan .fc2{position:absolute;left:36.5%;top:22%;width:27%;height:44%;border-radius:2cqw;background:#fff;box-shadow:0 1cqw 3cqw -1cqw rgba(0,0,0,.3);padding:3cqw;display:flex;flex-direction:column;gap:1.2cqw;transform-origin:50% 210%;transform:rotate(var(--fr));z-index:var(--i)}
.d-fan .fc2 i{height:2.2cqw;border-radius:1cqw;background:var(--g9);opacity:calc(.4 + var(--i) * .15)}
.d-fan .fc2 span{font:600 3.4cqw var(--fb);color:#5C636C;white-space:nowrap}
.d-fan .fc2 b{font:900 10cqw/1 var(--ft);color:var(--g9)}
.d-fan .fc2 small{margin-top:auto;font:700 3.4cqw/1.3 var(--fb);color:#1C2128;white-space:nowrap}
.d-fan .cap2{position:absolute;left:0;right:0;bottom:6%;text-align:center;font:700 4.6cqw var(--fb);color:#1C2128}
.play .d-fan .fc2{animation:fanK 2.8s cubic-bezier(.5,0,.2,1) .2s both}
.play .d-fan .cap2{animation:fadeIn .4s 2.6s both}
@keyframes fanK{0%{transform:translate(var(--sx),var(--sy)) rotate(var(--sr));opacity:0}12%{opacity:1}45%,58%{transform:translateY(calc(var(--i) * -.7cqw)) rotate(0deg)}100%{transform:rotate(var(--fr))}}

/* ── ⑩ 도형 쌓기: 도형이 떨어져 학교 모양 → 한 장의 제목으로 합쳐짐 ── */
.d-build{background:#fff}
.d-build .sh{position:absolute;display:block;left:12%;top:26%;width:76%;height:48%;border-radius:2cqw;background:#4A5563;clip-path:polygon(0 0,100% 0,100% 100%,0 100%)}
.d-build .s2{clip-path:polygon(0 0,100% 0,100% 100%,0 100%)}
.d-build .tt{position:absolute;left:12%;top:26%;width:76%;height:48%;padding:0 7%;display:flex;flex-direction:column;justify-content:center;gap:1.4cqw;color:#fff}
.d-build .tt span{font:700 4cqw var(--fm);opacity:.8}
.d-build .tt b{font:900 8cqw/1.15 var(--ft);letter-spacing:-.03em}
.play .d-build .sh{animation:bDrop .6s cubic-bezier(.4,0,.6,1.3) both,bMerge .8s cubic-bezier(.6,0,.2,1) 2.7s both;animation-delay:calc(var(--i) * .32s + .2s),2.7s}
.play .d-build .tt{animation:fadeIn .5s 3.5s both}
@keyframes bDrop{from{transform:translateY(-130cqh)}to{transform:none}}
@keyframes bMerge{from{left:var(--l);top:var(--t);width:var(--w);height:var(--h);background:var(--c);border-radius:0}to{left:12%;top:26%;width:76%;height:48%;background:#4A5563;border-radius:2cqw}}
.play .d-build .s2{animation:bDrop .6s cubic-bezier(.4,0,.6,1.3) both,bMergeT .8s cubic-bezier(.6,0,.2,1) 2.7s both;animation-delay:calc(var(--i) * .32s + .2s),2.7s}
@keyframes bMergeT{from{left:var(--l);top:var(--t);width:var(--w);height:var(--h);background:var(--c);border-radius:0;clip-path:polygon(50% 0,50% 0,100% 100%,0 100%)}to{left:12%;top:26%;width:76%;height:48%;background:#4A5563;border-radius:2cqw;clip-path:polygon(0 0,100% 0,100% 100%,0 100%)}}
.play .d-build .s4{animation-name:bDrop,bMergeC}
@keyframes bMergeC{from{left:var(--l);top:var(--t);width:var(--w);height:var(--h);background:var(--c);border-radius:50%}to{left:12%;top:26%;width:76%;height:48%;background:#4A5563;border-radius:2cqw}}

/* ── ⑩ 회전 글자 막대: 막대가 한 줄씩 돌아 뒷면의 바뀐 문구 ── */
.d-prism{background:#1E2329}
.d-prism .pg{position:absolute;left:10%;right:10%;top:16%;transform:rotate(-5deg);perspective:900px;perspective-origin:50% 120%}
.d-prism .br{position:relative;height:14cqw;margin-bottom:4cqw;transform-style:preserve-3d;transform:rotateX(90deg)}
.d-prism .fa,.d-prism .fb{position:absolute;inset:0;display:grid;place-items:center;font:900 8.6cqw/1 var(--ft);letter-spacing:-.03em;backface-visibility:hidden;-webkit-backface-visibility:hidden}
.d-prism .fa{background:#F4F1E8;color:#1E2329;transform:translateZ(7cqw)}
.d-prism .fb{background:var(--g10);color:#fff;transform:rotateX(-90deg) translateZ(7cqw)}
.d-prism .br:nth-child(2) .fb{background:#5E6A79}.d-prism .br:nth-child(3) .fb{background:#748091}
.play .d-prism .br{animation:prismR 1s cubic-bezier(.5,-.25,.3,1.35) both;animation-delay:calc(var(--i) * .3s + 1.2s)}
@keyframes prismR{from{transform:rotateX(0deg)}to{transform:rotateX(90deg)}}

/* ── ⑩ 렌즈 속 장면: 흐린 낱말 위를 렌즈가 지나가고, 렌즈 속만 진짜 색 ── */
/* ── ⑩ 렌즈 속 장면: 불 꺼진 학교(.out) 위를 렌즈가 지나가면 그 안만 불 켜진 같은 학교(.in, 1.22배) ──
   두 사진은 같은 3:2 구도라 틀(.fr) 기준 % 위치가 같다. 렌즈 자리 --lx · --ly(%) · 반지름 --lr · 배율 --lm 을 틀에서 움직인다.
   .in 은 렌즈 중심을 기준점으로 --lm 배 확대하고 그 자리를 원으로 잘라 낸다(돋보기). 끝 모습은 렌즈가 화면 전체로 커져 모두 켜진 학교 + 한 줄 */
.d-lens{background:#1B2440;overflow:hidden}
.d-lens .fr{position:absolute;left:50%;top:50%;width:max(100cqw,177.78cqh);height:max(56.25cqw,100cqh);translate:-50% -50%;container-type:size;
  --lx:50%;--ly:49%;--lr:120cqh;--lm:1}
.d-lens .out,.d-lens .in{position:absolute;inset:0;background:center/100% 100% no-repeat}
.d-lens .out{background-image:var(--img-LO)}
.d-lens .in{background-image:var(--img-LI);transform-origin:var(--lx) var(--ly);transform:scale(var(--lm));
  clip-path:circle(calc(var(--lr) / var(--lm)) at var(--lx) var(--ly))}
.d-lens .gl{position:absolute;left:var(--lx);top:var(--ly);width:calc(var(--lr) * 2);height:calc(var(--lr) * 2);translate:-50% -50%;border-radius:50%;opacity:0;pointer-events:none;
  box-shadow:0 0 0 1.6cqh #1C2128,0 0 0 2.2cqh rgba(255,255,255,.18),0 3cqh 6cqh rgba(0,0,0,.45),inset 0 0 4cqh rgba(255,255,255,.22);
  background:radial-gradient(circle at 32% 26%,rgba(255,255,255,.38),rgba(255,255,255,0) 22%),radial-gradient(circle at 70% 80%,rgba(255,255,255,.08),rgba(255,255,255,0) 30%)}
.d-lens .gl::after{content:"";position:absolute;right:-13%;bottom:-13%;width:30%;height:10%;border-radius:2cqh;background:#1C2128;rotate:45deg;transform-origin:left center}
.d-lens .lc{position:absolute;left:0;right:0;bottom:0;margin:0;padding:12cqh 5cqw 5cqh;z-index:2;background:linear-gradient(transparent,rgba(12,16,34,.82) 55%);color:#fff;opacity:0}
.d-lens .lc span{display:block;font:800 6.4cqh var(--fb);color:#FFB45E;letter-spacing:.08em}
.d-lens .lc b{display:block;margin-top:1.2cqh;font:900 min(7.2cqh,4.6cqw)/1.25 var(--ft);letter-spacing:-.02em}
.play .d-lens .fr{animation:lensWalk 5.8s both}
.play .d-lens .gl{animation:lensGlass 5.8s both}
.play .d-lens .lc{animation:fadeUp .6s 4.7s both}
/* 렌즈: 왼쪽 밖에서 들어와 불 켜진 창 셋(3층 왼쪽 · 2층 가운데 · 3층 오른쪽)에 머물렀다가, 가운데로 와서 화면 전체로 커진다 */
@keyframes lensWalk{
  0%{--lx:-20%;--ly:45%;--lr:24cqh;--lm:1.22;animation-timing-function:cubic-bezier(.3,0,.25,1)}
  16%,24%{--lx:27.5%;--ly:40.7%;--lr:24cqh;--lm:1.22;animation-timing-function:cubic-bezier(.45,0,.25,1)}
  36%,44%{--lx:38.8%;--ly:55.6%;--lr:24cqh;--lm:1.22;animation-timing-function:cubic-bezier(.45,0,.25,1)}
  56%,63%{--lx:66%;--ly:40.7%;--lr:24cqh;--lm:1.22;animation-timing-function:cubic-bezier(.6,0,.3,1)}
  70%{--lx:50%;--ly:49%;--lr:24cqh;--lm:1.22;animation-timing-function:cubic-bezier(.55,0,.2,1)}
  84%,100%{--lx:50%;--ly:49%;--lr:120cqh;--lm:1}}
@keyframes lensGlass{0%{opacity:1}72%{opacity:1}82%,100%{opacity:0}}


@media print{
  html,body{background:#fff;height:auto}
  .bar{display:none}
  .viewport{position:static;display:block}
  .stage{transform:none!important;width:auto;height:auto;position:static}
  .slide{position:relative;visibility:visible;opacity:1;width:1600px;height:900px;break-after:page}
  *,*::before,*::after{animation-duration:0s!important;animation-delay:0s!important;transition:none!important}
  .fw .fwt{opacity:1}
  .fullv{display:none!important}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.01s!important;animation-delay:0s!important;transition-duration:.01s!important}
}

